using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // Preserve EF Core 8 discriminator property name (EF 9 defaults to "$type").
            // Existing 500K documents use "Discriminator" and direct SQL queries reference it.
            entity.HasDiscriminator<string>("Discriminator");

            // Preserve EF Core 8 compound id format "Product|123" so existing documents
            // remain accessible (EF 9 defaults to key-only id).
            entity.HasRootDiscriminatorInJsonId(true);
        });
    }
}
